/**
 * The Mission Editor's own F10 map icon list (data/me-icons.json, generated by
 * scripts/data/gen-me-icons.py from <install>/MissionEditor/data/NewMap/images/draw/icons.lua).
 *
 * pydcs's `StandardIcon` knows nine of these; the editor's picker offers all of them, and
 * the file name is what a drawing's `file` field holds — confirmed against ME-saved
 * missions (`["primitiveType"] = "Icon"` with `["file"] = "P91000006.png"`).
 */
import { readFileSync } from 'node:fs';
import { packagePath } from '../paths.js';

export interface MeIconData {
  _source: string;
  _sha256: Record<string, string>;
  _dcsVersion: string | null;
  count: number;
  order: string[];
  icons: Record<string, string>;
}

let cache: MeIconData | undefined;
export function meIcons(): MeIconData {
  return (cache ??= JSON.parse(readFileSync(packagePath('data', 'me-icons.json'), 'utf8')) as MeIconData);
}
